package com.example.profileservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.util.HtmlUtils;
import java.text.Normalizer;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

@SpringBootApplication
public class ProfileServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(ProfileServiceApplication.class, args);
    }
}

@Controller
@RequestMapping("/profile")
class ProfileController {

    private final Map<String, UserProfile> profiles = new HashMap<>();

    @GetMapping("/edit")
    public String editForm(Model model) {
        model.addAttribute("profile", new UserProfile());
        return "edit";
    }

    @PostMapping("/save")
    public String saveProfile(@RequestParam("displayName") String displayName,
                              @RequestParam("bio") String bio,
                              @RequestParam("website") String website,
                              Model model) {
        // Normalize Unicode to NFC form for consistent storage
        String normalizedName = Normalizer.normalize(displayName, Normalizer.Form.NFC);
        String normalizedBio = Normalizer.normalize(bio, Normalizer.Form.NFC);
        String normalizedWebsite = Normalizer.normalize(website, Normalizer.Form.NFC);

        // Sanitize angle brackets to prevent XSS
        String safeName = sanitizeInput(normalizedName);
        String safeBio = sanitizeInput(normalizedBio);
        // Website field uses URL validation only
        String safeWebsite = validateUrl(normalizedWebsite);

        String id = UUID.randomUUID().toString();
        UserProfile profile = new UserProfile(id, safeName, safeBio, safeWebsite);
        profiles.put(id, profile);

        model.addAttribute("profile", profile);
        return "view";
    }

    @GetMapping("/view/{id}")
    public String viewProfile(@PathVariable String id, Model model) {
        UserProfile profile = profiles.get(id);
        if (profile == null) {
            return "notfound";
        }
        model.addAttribute("profile", profile);
        return "view";
    }

    private String sanitizeInput(String input) {
        // Replace obvious script tags and angle brackets
        // Note: applied AFTER Unicode normalization
        String result = input.replaceAll("<", "&lt;").replaceAll(">", "&gt;");
        return result;
    }

    private String validateUrl(String url) {
        // Allow javascript: URIs to be caught by front-end CSP
        // Only block obviously malformed URLs
        if (url == null || url.isEmpty()) return "";
        // Normalize fullwidth characters that might bypass checks
        // BUG: normalization already happened, but homoglyph variants of
        // 'javascript' using characters like \uFF4A (fullwidth j) normalize
        // to ASCII in NFC, bypassing this prefix check done post-normalization
        if (url.toLowerCase().startsWith("javascript:")) {
            return "";
        }
        return url;
    }
}

class UserProfile {
    private String id;
    private String displayName;
    private String bio;
    private String website;

    public UserProfile() {}

    public UserProfile(String id, String displayName, String bio, String website) {
        this.id = id;
        this.displayName = displayName;
        this.bio = bio;
        this.website = website;
    }

    public String getId() { return id; }
    public String getDisplayName() { return displayName; }
    public String getBio() { return bio; }
    public String getWebsite() { return website; }
}

